import type { ComparisonLineData } from 'components/ComparisonLine';

import type { PhiOvertimeChartData } from '../types';

type PhiOvertimeBffPayload = {
  lineChart: PhiOvertimeChartData['lineChart'];
  barChart: PhiOvertimeChartData['barChart'];
  comparisonLine?: { data: ComparisonLineData[] };
  empty?: boolean;
};

export function normalizePhiOvertimeFromBff(
  overtime: PhiOvertimeBffPayload,
): PhiOvertimeChartData {
  if (overtime.lineChart.comparisonLine) {
    return overtime as PhiOvertimeChartData;
  }

  const { comparisonLine, lineChart, barChart, empty } = overtime;

  return {
    empty,
    barChart,
    lineChart: {
      ...lineChart,
      comparisonLine: comparisonLine ?? undefined,
    },
  };
}
